CREATE TABLE `jabatan_target_persyaratan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `jabatan_target_id` bigint unsigned NOT NULL,
  `jenis_syarat` enum('PENDIDIKAN_MIN','BIDANG_ILMU','PENGALAMAN_MIN','LAINNYA','GOLONGAN_MIN','RUMPUN_JABATAN') NOT NULL,
  `deskripsi` text NOT NULL,
  `nilai_minimal` varchar(500) DEFAULT NULL COMMENT 'Nilai terstruktur syarat: skalar (III/d, S1_D4) ATAU daftar berkoma (BIDANG_ILMU, RUMPUN_JABATAN). Prosa tempatnya kolom deskripsi.',
  `durasi_tahun_min` tinyint unsigned DEFAULT NULL COMMENT 'Lama minimal pada jenjang di nilai_minimal, dalam TAHUN. NULL = tidak dipersyaratkan.',
  PRIMARY KEY (`id`),
  KEY `idx_jtp_target` (`jabatan_target_id`),
  CONSTRAINT `fk_jtp_target` FOREIGN KEY (`jabatan_target_id`) REFERENCES `jabatan_target` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=392 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Syarat minimal per jabatan target (Master Jabatan Target & Persyaratan)';
