INSERT INTO `jabatan_target_persyaratan` VALUES (312,386,'PENDIDIKAN_MIN','Pendidikan minimal S2 (PP 11/2017).','S2',NULL),(313,386,'BIDANG_ILMU','Bidang pendidikan: Teknik / Ekonomi Studi Pembangunan / Manajemen / Akuntansi / Hukum / Komunikasi / Administrasi Negara / Administrasi Publik / Teknik Informatika (semua jurusan). Sel aslinya menutup daftarnya dengan \"(semua jurusan)\", jadi gerbang kelayakan diisi \"semua\" — daftar rumpun di atas dipakai indikator rubrik Kesesuaian Bidang Ilmu untuk MENILAI, bukan untuk menggugurkan.','semua',NULL),(314,386,'GOLONGAN_MIN','Golongan minimal IV/b (PP 11/2017).','IV/b',NULL),(315,386,'PENGALAMAN_MIN','Sedang atau pernah menduduki jabatan administrator (kepala bagian / kepala sub direktorat / kepala bidang / kepala balai) atau jabatan fungsional jenjang Ahli Madya (Pembina Jasa Konstruksi Ahli Madya / Pengelola Pengadaan Barang dan Jasa Ahli Madya) paling singkat 2 tahun','III',2),(316,434,'PENDIDIKAN_MIN','Pendidikan minimal D4/S1 (PP 11/2017).','S1_D4',NULL),(317,434,'BIDANG_ILMU','Bidang pendidikan: Teknik / Ekonomi Studi Pembangunan / Manajemen / Akuntansi / Hukum / Komunikasi / Administrasi Negara / Administrasi Publik / Teknik Informatika (semua jurusan). Sel aslinya menutup daftarnya dengan \"(semua jurusan)\", jadi gerbang kelayakan diisi \"semua\" — daftar rumpun di atas dipakai indikator rubrik Kesesuaian Bidang Ilmu untuk MENILAI, bukan untuk menggugurkan.','semua',NULL),(318,434,'GOLONGAN_MIN','Golongan minimal III/d (PP 11/2017).','III/d',NULL),(319,434,'PENGALAMAN_MIN','Memiliki pengalaman pada jabatan pengawas (kepala subbagian / kepala seksi) paling singkat 3 tahun, atau jabatan fungsional setingkat pengawas (Pembina Jasa Konstruksi Ahli Muda / Pengelola Pengadaan Barang dan Jasa Ahli Muda) sesuai bidang tugas jabatan yang akan diduduki','IV',3),(320,435,'PENDIDIKAN_MIN','Pendidikan minimal D4/S1 (PP 11/2017).','S1_D4',NULL),(321,435,'BIDANG_ILMU','Bidang pendidikan: Teknik / Ekonomi Studi Pembangunan / Ma